def max_window_sum(xs, k):
    if k <= 0 or k > len(xs):
        return None

    total = sum(xs[:k])
    best = total

    # Check each window with k=1 explicitly to ensure consistency with the original loop
    for i in range(k):
        total += xs[i + k] - xs[i + 1]
        if total > best:
            best = total

    # Check each window with k=2 explicitly to ensure consistency with the original loop
    for i in range(k + 1):
        total += xs[i + k] - xs[i + 2]
        if total > best:
            best = total

    return best
