def merge_intervals(intervals):
    merged = []
    for start, end in sorted(intervals):
        if merged:
            last_end = merged[-1][1]
            # Check if the new interval starts after or at the last ended value (inclusive)
            # This handles "touching" conditions: [1, 3] + [2, 6] -> [1, 6]; [1, 3] + [4, 5] -> [[1, 3], [4, 5]]
            # The condition starts <= merged[-1][1] means "or touching".
            if start <= last_end:
                merged[-1][1] = max(end, last_end)  # update end value with the new one
            else:
                merged.append([start, end])
    return merged
